parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
const lastRun = staticData.lastRunTimestamp || 0;
const transcripts = $input.first().json.data.transcripts || [];

const newTranscripts = transcripts.filter(t => {
  const tDate = parseInt(t.date || '0');
  return tDate > lastRun;
});

staticData.lastRunTimestamp = Math.floor(Date.now() / 1000);

if (newTranscripts.length === 0) {
  return [];
}

return newTranscripts.map(t => ({ json: t }));

const item = $input.first().json;

// Build full transcript text from sentences
const sentences = item.sentences || [];
const transcriptText = sentences.map(s => `${s.speaker_name}: ${s.text}`).join('\n');

// Extract attendees
const attendees = item.meeting_attendees || [];
const organizer = item.organizer_email || '';

// Find prospect (first attendee who is not the organizer)
const prospect = attendees.find(a => a.email !== organizer) || attendees[0] || {};

// Attempt to extract company from prospect email domain
const prospectEmail = prospect.email || '';
let company = '';
if (prospectEmail) {
  const domain = prospectEmail.split('@')[1] || '';
  company = domain.split('.')[0] || '';
  company = company.charAt(0).toUpperCase() + company.slice(1);
}

return [{
  json: {
    fireflies_id: item.id,
    title: item.title || 'Untitled Call',
    call_date: item.date,
    duration_seconds: item.duration || 0,
    organizer_email: organizer,
    prospect_name: prospect.displayName || 'Unknown',
    prospect_email: prospectEmail,
    company: company,
    transcript_url: item.transcript_url || '',
    summary_bullets: (item.summary && item.summary.shorthand_bullet) || '',
    transcript_text: transcriptText,
    attendees: JSON.stringify(attendees)
  }
}];

const response = $input.first().json;
const callData = $('Insert Call to Supabase').first().json;

// Extract the text content from Claude's response
const content = response.content || [];
const textBlock = content.find(b => b.type === 'text');
const rawText = textBlock ? textBlock.text : '{}';

// Parse the JSON from Claude's response
let insights;
try {
  insights = JSON.parse(rawText);
} catch (e) {
  // Try to extract JSON from possible markdown code blocks
  const jsonMatch = rawText.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    insights = JSON.parse(jsonMatch[1].trim());
  } else {
    throw new Error('Failed to parse Claude response as JSON: ' + rawText.substring(0, 200));
  }
}

// Get the call ID from the Supabase insert response
const callId = Array.isArray(callData) ? callData[0].id : callData.id;

return [{
  json: {
    call_id: callId,
    fireflies_id: $('Parse Call Data').first().json.fireflies_id,
    title: $('Parse Call Data').first().json.title,
    prospect_name: $('Parse Call Data').first().json.prospect_name,
    company: $('Parse Call Data').first().json.company,
    transcript_url: $('Parse Call Data').first().json.transcript_url,
    sentiment: insights.sentiment || 'neutral',
    key_topics: insights.key_topics || [],
    objections: insights.objections || [],
    action_items: insights.action_items || [],
    buying_signals: insights.buying_signals || [],
    risk_factors: insights.risk_factors || [],
    next_steps: insights.next_steps || '',
    deal_stage_suggestion: insights.deal_stage_suggestion || 'discovery',
    key_turning_point: insights.key_turning_point || '',
    competitor_mentions: insights.competitor_mentions || [],
    pain_points: insights.pain_points || [],
    confidence_score: insights.confidence_score || 0
  }
}];

